    <section className="section section-soft"><div className="container"><div className="section-heading"><div><Eyebrow>CORE EXPERTISE</Eyebrow><h2>Improve the parts of commerce that <em>move the whole.</em></h2></div>{link('/services','Explore all services →','text-link')}</div><div className="service-grid">{services.slice(0,6).map((s,i)=><ServiceCard key={s[5]} service={s} index={i}/>)}</div></div></section>
